/**
 * The Salt Monopoly — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { SALT_MONOPOLY_TEMPLATE } from '../salt-monopoly';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Salt Monopoly — template structure", () => {
  it('carries its identity', () => {
    expect(SALT_MONOPOLY_TEMPLATE.id).toBe('encounter.town.salt_monopoly');
    expect(SALT_MONOPOLY_TEMPLATE.reach).toBe('gold');
    expect(SALT_MONOPOLY_TEMPLATE.rarityTier).toBe(2);
    expect(SALT_MONOPOLY_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = SALT_MONOPOLY_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['salt.rouse_the_backers', 'salt.cloud_the_tally']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['chaos', 'spirit']);
  });

  it('step 1 deals the authored hand', () => {
    const step = SALT_MONOPOLY_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['salt.weigh_the_coin_true', 'salt.stretch_the_hour']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['order', 'time']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(SALT_MONOPOLY_TEMPLATE.settings).toEqual(['urban']);
    expect(SALT_MONOPOLY_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(SALT_MONOPOLY_TEMPLATE.consequenceDraw).toEqual(['possession', 'story_seed']);
    expect(SALT_MONOPOLY_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.salt_monopoly',
          reach: 'gold',
          rarityTier: 2,
        }),
        SALT_MONOPOLY_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
